eClient\n private lateinit var mockLocalDataSource: LocalDataSource\n private lateinit var mockPostgrest: Postgrest\n private lateinit var mockQueryBuilder: PostgrestQueryBuilder\n\n @Before\n fun setup() {\n // Initialize mocks\n mockF1StandingsApi = mockk()\n mockSupabaseClient = mockk()\n mockLocalDataSource = mockk()\n mockPostgrest = mockk()\n mockQueryBuilder = mockk()\n\n // Mock the supabase client postgrest property\n every { mockSupabaseClient.postgrest } returns mockPostgrest\n every { mockPostgrest.get(any<String>()) } returns mockQueryBuilder\n\n // Create the repository instance\n repository = F1StandingRepositoryImpl(\n f1StandingsApi = mockF1StandingsApi,\n supabaseClient = mockSupabaseClient,\n localDataSource = mockLocalDataSource\n )\n\n // Reset AppLaunchManager state before each test\n AppLaunchManager.hasFetchedConstructorStandings = false\n AppLaunchManager.hasFetchedDriverStandings = false\n AppLaunchManager.fetchedConstructorDetails.clear()\n AppLaunchManager.fetchedDriverDetails.clear()\n }\n\n @After\n fun tearDown() {\n clearAllMocks()\n // Reset AppLaunchManager state after each test\n AppLaunchManager.hasFetchedConstructorStandings = false\n AppLaunchManager.hasFetchedDriverStandings = false\n AppLaunchManager.fetchedConstructorDetails.clear()\n AppLaunchManager.fetchedDriverDetails.clear()\n }\n\n @Test\n fun `getConstructorStandings should fetch from network when not previously fetched`() = runTest {\n // Given\n val season = \"2024\"\n val mockResponse = mockk<ConstructorStandingsResponse>()\n val mockConstructorStandings = listOf(\n ConstructorStandingsInfo(\n position = \"1\",\n points = \"300\",\n wins = \"8\",\n constructorId = \"red_bull\",\n url = \"http://example.com\",\n name = \"Red Bull Racing\",\n nationality = \"Austrian\"\n )\n )\n\n every { runBlocking { mockF1StandingsApi.getConstructorStandings(season) } } returns mockResponse\n every { mockResponse.toConstructorInfoList() } returns mockConstructorStandings\n coEvery { mockLocalDataSource.insertConstructorStandingsListInDB(any()) } just Runs\n\n // When & Then\n repository.getConstructorStandings(season).test {\n // First emission should be loading with network fetch\n val loading = awaitItem()\n assertTrue(loading is Resource.Loading && loading.isFetchingFromNetwork == true)\n\n // Second emission should be success with data\n val success = awaitItem()\n assertTrue(success is Resource.Success)\n assertEquals(mockConstructorStandings, success.data)\n\n awaitComplete()\n }\n\n // Verify API was called\n coVerify { mockF1StandingsApi.getConstructorStandings(season) }\n coVerify { mockLocalDataSource.insertConstructorStandingsListInDB(mockConstructorStandings) }\n assertTrue(AppLaunchManager.hasFetchedConstructorStandings)\n }\n\n @Test\n fun `getConstructorStandings should fetch from database when previously fetched`() = runTest {\n // Given\n val season = \"2024\"\n val mockConstructorStandings = listOf(\n ConstructorStandingsInfo(\n position = \"1\",\n points = \"300\",\n wins = \"8\",\n constructorId = \"red_bull\",\n url = \"http://example.com\",\n name = \"Red Bull Racing\",\n nationality = \"Austrian\"\n )\n )\n\n AppLaunchManager.hasFetchedConstructorStandings = true\n coEvery { mockLocalDataSource.getConstructorStandingsListFromDB() } returns mockConstructorStandings\n\n // When & Then\n repository.getConstructorStandings(season).test {\n // First emission should be loading without network fetch\n val loading = awaitItem()\n assertTrue(loading is Resource.Loading && loading.isFetchingFromNetwork == false)\n\n // Second emission should be success with data from DB\n val success = awaitItem()\n assertTrue(success is Resource.Success)\n assertEquals(mockConstructorStandings, success.data)\n\n awaitComplete()\n }\n\n // Verify API was not called but DB was\n coVerify(exactly = 0) { mockF1StandingsApi.getConstructorStandings(any()) }\n coVerify { mockLocalDataSource.getConstructorStandingsListFromDB() }\n }\n\n @Test\n fun `getConstructorStandings should handle IOException`() = runTest {\n // Given\n val season = \"2024\"\n val exception = IOException(\"Network error\")\n\n coEvery { mockF1StandingsApi.getConstructorStandings(season) } throws exception\n\n // When & Then\n repository.getConstructorStandings(season).test {\n // First emission should be loading\n val loading = awaitItem()\n assertTrue(loading is Resource.Loading)\n\n // Second emission should be error\n val error = awaitItem()\n assertTrue(error is Resource.Error)\n\n awaitComplete()\n }\n }\n\n @Test\n fun `getConstructorStandings should handle HttpException`() = runTest {\n // Given\n val season = \"2024\"\n val httpException = mockk<HttpException>()\n\n coEvery { mockF1StandingsApi.getConstructorStandings(season) } throws httpException\n\n // When & Then\n repository.getConstructorStandings(season).test {\n // First emission should be loading\n val loading = awaitItem()\n assertTrue(loading is Resource.Loading)\n\n // Second emission should be error\n val error = awaitItem()\n assertTrue(error is Resource.Error)\n\n awaitComplete()\n }\n }\n\n @Test\n fun `getDriverStandings should fetch from network when not previously fetched`() = runTest {\n // Given\n val season = \"2024\"\n val mockResponse = mockk<DriverStandingsResponse>()\n val mockDriverStandings = listOf(\n DriverStandingsInfo(\n position = \"1\",\n points = \"150\",\n wins = \"5\",\n driverId = \"verstappen\",\n url = \"http://example.com\",\n givenName = \"Max\",\n familyName = \"Verstappen\",\n dateOfBirth = \"1997-09-30\",\n nationality = \"Dutch\",\n constructorId = \"red_bull\",\n constructorName = \"Red Bull Racing\",\n constructorNationality = \"Austrian\"\n )\n )\n\n every { runBlocking { mockF1StandingsApi.getDriverStandings(season) } } returns mockResponse\n every { mockResponse.toDriverStandingsInfoList() } returns mockDriverStandings\n coEvery { mockLocalDataSource.insertDriverStandingsListInDB(any()) } just Runs\n\n // When & Then\n repository.getDriverStandings(season).test {\n // First emission should be loading with network fetch\n val loading = awaitItem()\n assertTrue(loading is Resource.Loading && loading.isFetchingFromNetwork == true)\n\n // Second emission should be success with data\n val success = awaitItem()\n assertTrue(success is Resource.Success)\n assertEquals(mockDriverStandings, success.data)\n\n awaitComplete()\n }\n\n // Verify API was called\n coVerify { mockF1StandingsApi.getDriverStandings(season) }\n coVerify { mockLocalDataSource.insertDriverStandingsListInDB(mockDriverStandings) }\n assertTrue(AppLaunchManager.hasFetchedDriverStandings)\n }\n\n @Test\n fun `getDriverStandings should fetch from database when previously fetched`() = runTest {\n // Given\n val season = \"2024\"\n val mockDriverStandings = listOf(\n DriverStandingsInfo(\n position = \"1\",\n points = \"150\",\n wins = \"5\",\n driverId = \"verstappen\",\n url = \"http://example.com\",\n givenName = \"Max\",\n familyName = \"Verstappen\",\n dateOfBirth = \"1997-09-30\",\n nationality = \"Dutch\",\n constructorId = \"red_bull\",\n constructorName = \"Red Bull Racing\",\n constructorNationality = \"Austrian\"\n )\n )\n\n AppLaunchManager.hasFetchedDriverStandings = true\n coEvery { mockLocalDataSource.getDriverStandingsListFromDB() } returns mockDriverStandings\n\n // When & Then\n repository.getDriverStandings(season).test {\n // First emission should be loading without network fetch\n val loading = awaitItem()\n assertTrue(loading is Resource.Loading && loading.isFetchingFromNetwork == false)\n\n // Second emission should be success with data from DB\n val success = awaitItem()\n assertTrue(success is Resource.Success)\n assertEquals(mockDriverStandings, success.data)\n\n awaitComplete()\n }\n\n // Verify API was not called but DB was\n coVerify(exactly = 0) { mockF1StandingsApi.getDriverStandings(any()) }\n coVerify { mockLocalDataSource.getDriverStandingsListFromDB() }\n }\n\n @Test\n fun `getF1ConstructorDetails should fetch from network when not previously fetched`() = runTest {\n // Given\n val constructorId = \"red_bull\"\n val mockConstructorDetails = ConstructorDetails(\n constructorId = constructorId,\n name = \"Red Bull Racing\",\n nationality = \"Austrian\",\n description = \"Austrian racing team\",\n teamPrincipal = \"Christian Horner\",\n firstSeasonYear = \"2005\",\n lastSeasonYear = null,\n totalRaceEntries = \"300\",\n totalRaceStarts = \"300\",\n totalRaceWins = \"100\",\n totalRacePodiums = \"200\",\n totalSeasonWins = \"5\",\n photoUrl = \"http://example.com/photo.jpg\"\n )\n\n val mockResult = mockk<PostgrestResult>()\n coEvery { mockQueryBuilder.select(any<PostgrestQueryBuilder.() -> Unit>()) } returns mockResult\n every { mockResult.decodeSingleOrNull<ConstructorDetails>() } returns mockConstructorDetails\n coEvery { mockLocalDataSource.insertConstructorDetailsInDB(any()) } just Runs\n\n // When & Then\n repository.getF1ConstructorDetails(constructorId).test {\n // First emission should be loading with network fetch\n val loading = awaitItem()\n assertTrue(loading is Resource.Loading && loading.isFetchingFromNetwork == true)\n\n // Second emission should be success with data\n val success = awaitItem()\n assertTrue(success is Resource.Success)\n assertEquals(mockConstructorDetails, success.data)\n\n awaitComplete()\n }\n\n // Verify Supabase was called\n coVerify { mockLocalDataSource.insertConstructorDetailsInDB(mockConstructorDetails) }\n assertTrue(AppLaunchManager.fetchedConstructorDetails.contains(constructorId))\n }\n\n @Test\n fun `getF1ConstructorDetails should fetch from database when previously fetched`() = runTest {\n // Given\n val constructorId = \"red_bull\"\n val mockConstructorDetails = ConstructorDetails(\n constructorId = constructorId,\n name = \"Red Bull Racing\",\n nationality = \"Austrian\",\n description = \"Austrian racing team\",\n teamPrincipal = \"Christian Horner\",\n firstSeasonYear = \"2005\",\n lastSeasonYear = null,\n totalRaceEntries = \"300\",\n totalRaceStarts = \"300\",\n totalRaceWins = \"100\",\n totalRacePodiums = \"200\",\n totalSeasonWins = \"5\",\n photoUrl = \"http://example.com/photo.jpg\"\n )\n\n AppLaunchManager.fetchedConstructorDetails.add(constructorId)\n coEvery { mockLocalDataSource.getConstructorDetailsFromDB(constructorId) } returns mockConstructorDetails\n\n // When & Then\n repository.getF1ConstructorDetails(constructorId).test {\n // First emission should be loading without network fetch\n val loading = awaitItem()\n assertTrue(loading is Resource.Loading && loading.isFetchingFromNetwork == false)\n\n // Second emission should be success with data from DB\n val success = awaitItem()\n assertTrue(success is Resource.Success)\n assertEquals(mockConstructorDetails, success.data)\n\n awaitComplete()\n }\n\n // Verify DB was called but not Supabase\n coVerify { mockLocalDataSource.getConstructorDetailsFromDB(constructorId) }\n coVerify(exactly = 0) { mockQueryBuilder.select(any<PostgrestQueryBuilder.() -> Unit>()) }\n }\n\n @Test\n fun `getF1DriverDetails should fetch from network when not previously fetched`() = runTest {\n // Given\n val driverId = \"verstappen\"\n val mockDriverDetails = DriverDetails(\n driverId = driverId,\n permanentNumber = \"1\",\n code = \"VER\",\n givenName = \"Max\",\n familyName = \"Verstappen\",\n dateOfBirth = \"1997-09-30\",\n nationality = \"Dutch\",\n description = \"Dutch Formula 1 driver\",\n totalSeasonWins = \"3\",\n totalRaceWins = \"50\",\n totalRacePodiums = \"90\",\n totalRaceEntries = \"150\",\n totalRaceStarts = \"150\",\n photoUrl = \"http://example.com/max.jpg\"\n )\n\n val mockResult = mockk<PostgrestResult>()\n coEvery { mockQueryBuilder.select(any<PostgrestQueryBuilder.() -> Unit>()) } returns mockResult\n every { mockResult.decodeSingleOrNull<DriverDetails>() } returns mockDriverDetails\n coEvery { mockLocalDataSource.insertDriverDetailsInDB(any()) } just Runs\n\n // When & Then\n repository.getF1DriverDetails(driverId).test {\n // First emission should be loading with network fetch\n val loading = awaitItem()\n assertTrue(loading is Resource.Loading && loading.isFetchingFromNetwork == true)\n\n // Second emission should be success with data\n val success = awaitItem()\n assertTrue(success is Resource.Success)\n assertEquals(mockDriverDetails, success.data)\n\n awaitComplete()\n }\n\n // Verify Supabase was called\n coVerify { mockLocalDataSource.insertDriverDetailsInDB(mockDriverDetails) }\n assertTrue(AppLaunchManager.fetchedDriverDetails.contains(driverId))\n }\n\n @Test\n fun `getF1DriverDetails should fetch from database when previously fetched`() = runTest {\n // Given\n val driverId = \"verstappen\"\n val mockDriverDetails = DriverDetails(\n driverId = driverId,\n permanentNumber = \"1\",\n code = \"VER\",\n givenName = \"Max\",\n familyName = \"Verstappen\",\n dateOfBirth = \"1997-09-30\",\n nationality = \"Dutch\",\n description = \"Dutch Formula 1 driver\",\n totalSeasonWins = \"3\",\n totalRaceWins = \"50\",\n totalRacePodiums = \"90\",\n totalRaceEntries = \"150\",\n totalRaceStarts = \"150\",\n photoUrl = \"http://example.com/max.jpg\"\n )\n\n AppLaunchManager.fetchedDriverDetails.add(driverId)\n coEvery { mockLocalDataSource.getDriverDetailsFromDB(driverId) } returns mockDriverDetails\n\n // When & Then\n repository.getF1DriverDetails(driverId).test {\n // First emission should be loading without network fetch\n val loading = awaitItem()\n assertTrue(loading is Resource.Loading && loading.isFetchingFromNetwork == false)\n\n // Second emission should be success with data from DB\n val success = awaitItem()\n assertTrue(success is Resource.Success)\n assertEquals(mockDriverDetails, success.data)\n\n awaitComplete()\n }\n\n // Verify DB was called but not Supabase\n coVerify { mockLocalDataSource.getDriverDetailsFromDB(driverId) }\n coVerify(exactly = 0) { mockQueryBuilder.select(any<PostgrestQueryBuilder.() -> Unit>()) }\n }\n\n @Test\n fun `getConstructorStandings should